        { when: "2018", label: "MM CCM 48M, LLC buys the mall and assumes the host lease" },
        { when: "A few months after the purchase", label: "MM CCM 48M Leasing ends the lease and gives ATC 30 days to remove its equipment after the mall closes" },
        { when: "June 24, 2024", label: "471st District Court, Collin County (No. 471-03806-2023) signs judgment for the owners" },
        { when: "December 18, 2025", label: "Fifth Court of Appeals issues a memorandum opinion, later withdrawn" },
        { when: "January 29, 2026", label: "Substituted opinion reverses, renders judgment for ATC on breach of contract and remands fees and the claims against MM CCM 48M Leasing" },
        { when: "April 15, 2026", label: "Mandate issues", current: true }
