        { when: "February 4, 2025", label: "Fourteenth Court of Appeals reverses and remands" },
        { when: "October 24, 2025", label: "Supreme Court of Texas denies petition for review" },
        { when: "December 5, 2025", label: "Mandate issues, returning the case to the trial court", current: true }
