        { when: "December 18, 2024", label: "Adams County circuit court rules for Link Media on conversion and interference, and for Michelmann on rent ($19,907.97)" },
        { when: "October 23, 2025", label: "Circuit court denies both sides' post-judgment motions" },
        { when: "October 26, 2026", label: "Appellate Court, Fourth District reverses on conversion, directs nominal damages, and otherwise affirms", current: true }
